/* Discovery and private notebook: large targets and a single-column mobile path. */
.discovery-nav{display:flex;justify-content:center;gap:24px;flex-wrap:wrap;border-top:1px solid var(--line,#dfe4d9);padding:8px 20px;font-size:13px;background:#f5f5ed}
.discovery-nav a{display:flex;align-items:center;min-height:36px;text-decoration:none;font-weight:700}.discovery-nav a[aria-current=page]{text-decoration:underline;text-underline-offset:5px}
.return-tools{margin-block:48px}.return-tools>h2{margin:0 0 24px}.tool-entry{border:1px solid #ced7c7;background:#f0f2e7;border-radius:18px;padding:26px;text-decoration:none;display:flex;flex-direction:column;gap:9px;transition:transform .18s,border-color .18s}
.tool-entry:hover{transform:translateY(-3px);border-color:#46644d}.tool-entry h3{margin:6px 0;font-size:22px}.tool-entry p{margin:0 0 10px;line-height:1.8;color:#495b4e}.tool-entry strong{margin-top:auto}.tool-entry-number{font-size:11px;letter-spacing:.1em;color:#415343;font-weight:700}
.coverage-strip{display:flex;flex-wrap:wrap;gap:14px 32px;margin:26px 0}.coverage-strip span{font-size:13px;color:#405147}.coverage-strip b{font-size:30px;color:#173b32;margin-right:5px}
.inline-actions{display:flex;flex-wrap:wrap;gap:12px 20px;align-items:center;margin:20px 0}.inline-actions>a:not(.button){display:inline-flex;align-items:center;min-height:44px;font-weight:600}
.gym{padding:24px;display:flex;flex-direction:column;gap:10px;min-width:0}.gym h2{font-size:21px;line-height:1.5;margin:0}.gym h2 a{text-decoration:none}.gym>.card-meta{align-items:flex-start;flex-wrap:wrap;gap:8px}.gym>.card-meta .eyebrow{margin:0}.gym p{margin:6px 0}.gym .compare-pick{margin-top:auto;min-height:48px;align-items:center;gap:12px;padding-top:16px;border-top:1px solid #dfe4d9}.gym .compare-pick input{flex-shrink:0;min-height:22px;width:22px;height:22px}.gym .compare-pick span{line-height:1.5;font-size:13px}
.status-badge{border-radius:6px;background:#e8eee0;color:#294932;padding:5px 8px;font-size:11px;line-height:1.5;font-weight:700}.status-badge.closed{background:#f3e5dc;color:#653c23}.closure-date{font-weight:700;color:#653c23}
.gym-comparison-table th,.gym-comparison-table td{white-space:normal;min-width:190px}.gym-comparison-table th:first-child{min-width:130px}.comparison-panel{margin-block:24px;scroll-margin-top:148px}.comparison-panel>.section-head{align-items:center;gap:12px;flex-wrap:wrap}.gym-comparison-table thead button{display:block;min-height:44px;margin-top:12px;padding:6px 12px;font-size:12px}.table-scroll{overscroll-behavior-x:contain}
.compare-dock{display:flex;position:fixed;z-index:25;bottom:20px;left:50%;transform:translateX(-50%);align-items:center;justify-content:center;gap:14px;padding:12px 20px;background:#173b32;color:#fff;border-radius:16px;box-shadow:0 10px 36px #142c3026;max-width:calc(100vw - 24px);width:max-content}.compare-dock .button{background:#deed9b;color:#173b32;white-space:nowrap;min-height:44px}.compare-dock .ghost{background:transparent;color:#fff;border-color:#769682}.compare-dock>span{font-size:13px;white-space:nowrap}.has-gym-comparison .site-footer{padding-bottom:130px}
.history-list{list-style:none;padding:0;margin:24px 0}.history-list li{display:grid;grid-template-columns:130px 1fr;gap:24px;border-left:2px solid #b7caa5;padding:22px 26px;margin-left:6px;position:relative}.history-list li:before{content:'';position:absolute;left:-7px;top:28px;width:12px;height:12px;border-radius:50%;background:#173b32}.history-list time{font-size:15px;font-weight:700}.history-list h3{margin:0;font-size:20px}.history-list p{margin:8px 0;color:#526355}
.field-sources div{border-bottom:1px solid #dae1d6;padding:10px 0;display:grid;grid-template-columns:160px 1fr;gap:16px}.field-sources dt code{font-size:12px;white-space:normal;overflow-wrap:anywhere}.field-sources dd{margin:0;font-size:13px;line-height:1.8;overflow-wrap:anywhere}.detail-layout>div,.detail-layout>aside{min-width:0}
.glossary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.glossary-term{padding:26px;scroll-margin-top:148px;min-width:0}.glossary-term:target{outline:3px solid #647846;outline-offset:3px}.glossary-term h2{font-size:24px;margin:16px 0 4px}.term-english{color:#405548;font-size:12px;font-weight:700;letter-spacing:.05em;margin:0 0 18px}.glossary-term p{line-height:1.85}.term-caution{font-size:13px;padding:12px 14px;border-left:3px solid #b0c286;background:#f1f3e9}.term-sources{font-size:12px;margin-top:18px}.term-sources summary{min-height:44px;cursor:pointer;padding-block:12px}.article-terms{border-block:1px solid #dfe4d9;padding:22px 0;margin:30px 0}.article-terms h2{font-size:18px}.term-chips{display:flex;flex-wrap:wrap;gap:8px}.term-chip{border:1px solid #c3d1b9;border-radius:100px;min-height:44px;padding:9px 16px;display:inline-flex;align-items:center;font-size:13px;text-decoration:none;background:#f0f4e8}
.notebook-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:36px;margin-top:28px;align-items:start}.notebook-layout>div,.notebook-layout>section{min-width:0}.notebook-form-card{border:1px solid #d3ddce;border-radius:18px;background:#fffefa;padding:26px}.notebook-form-card>h2{font-size:22px;margin:0 0 20px;scroll-margin-top:150px}.notebook-layout form>label{display:flex;flex-direction:column;gap:8px;margin:16px 0;font-size:14px;font-weight:600}.notebook-layout .form-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:14px 0}.notebook-layout .form-pair label{display:flex;flex-direction:column;gap:8px;font-size:13px;font-weight:600;min-width:0}.notebook-layout input,.notebook-layout select,.notebook-layout textarea{font-family:inherit;font-size:16px;border:1px solid #c3cebe;border-radius:9px;background:#fffefa;color:#173b32;min-height:46px;padding:11px 12px;width:100%;max-width:100%;box-sizing:border-box}.notebook-layout textarea{resize:vertical}.notebook-layout input[type=hidden]{display:none}.notebook-layout input[type=file]{font-size:13px;padding:10px 0;border:0}.import-label{display:block;margin-top:20px}.notebook-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;background:#173b32;color:#f1f6df;border-radius:18px;padding:24px 16px}.notebook-summary span{font-size:11px;line-height:1.6}.notebook-summary b{display:block;font-size:27px;line-height:1.2;margin-bottom:6px}.note-filters{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:12px;margin:20px 0}.note-filters label{font-size:12px;display:flex;flex-direction:column;gap:8px}.note-filters input,.note-filters select{font-size:14px}.note-card{border:1px solid #d9e0d3;border-radius:16px;padding:24px;background:#fffefa;margin:16px 0;overflow-wrap:anywhere}.note-card h3{font-size:22px;line-height:1.5;margin:12px 0}.note-card time{font-size:13px}.note-card .inline-actions{margin-bottom:0}.note-text{white-space:pre-wrap;line-height:1.8}.next-move{background:#eef3e3;border-left:3px solid #95ad66;padding:14px 16px;margin:16px 0}.next-move strong{font-size:12px}.next-move p{margin:6px 0 0}.text-button{appearance:none;border:0;background:transparent;text-decoration:underline;text-underline-offset:4px;font:inherit;color:#635145;min-height:44px;padding:10px 14px;cursor:pointer}
@media(max-width:760px){.discovery-nav{gap:4px 18px;padding:3px 16px;justify-content:space-around;font-size:12px}.discovery-nav a{min-height:40px}.notebook-layout{grid-template-columns:1fr;gap:24px}.notebook-form-card{padding:20px}.glossary-grid{grid-template-columns:1fr}.glossary-term{padding:22px}.field-sources div{grid-template-columns:1fr;gap:4px}.coverage-strip{gap:10px 20px}.coverage-strip b{font-size:25px}.coverage-strip span{font-size:12px}.compare-dock{bottom:calc(76px + env(safe-area-inset-bottom));gap:8px;padding:9px 12px;width:calc(100% - 24px);border-radius:12px}.compare-dock .button{font-size:12px;padding:9px 12px}.compare-dock>span{font-size:11px}.has-gym-comparison .site-footer{padding-bottom:190px}.history-list li{grid-template-columns:1fr;gap:8px;padding:20px}.history-list h3{font-size:18px}.return-tools{margin-block:30px}.tool-entry{padding:22px}.tool-entry:hover{transform:none}.gym-comparison-table th,.gym-comparison-table td{min-width:180px}.gym-comparison-table th:first-child{min-width:110px}.notebook-summary{padding:20px 16px}}
@media(prefers-reduced-motion:reduce){.tool-entry{transition:none}.tool-entry:hover{transform:none}}

@media(max-width:420px){[data-note-form] .form-pair:first-of-type{grid-template-columns:1fr}}
